using System.Collections.Generic;public class Solution{public IList<int> FindMinHeightTrees(int n,int[][]e){if(n==1)return new List<int>{0};var g=new List<int>[n];int[]d=new int[n];for(int i=0;i<n;i++)g[i]=new();foreach(var x in e){g[x[0]].Add(x[1]);g[x[1]].Add(x[0]);d[x[0]]++;d[x[1]]++;}var q=new Queue<int>();for(int i=0;i<n;i++)if(d[i]==1)q.Enqueue(i);int left=n;while(left>2){int z=q.Count;left-=z;while(z-->0){int u=q.Dequeue();foreach(int v in g[u])if(--d[v]==1)q.Enqueue(v);}}return new List<int>(q);}}
